import { AxeBuilder } from "@axe-core/playwright";
import type { Page } from "@playwright/test";
import { expect, test } from "./notebook";

const TEXT = `A short introduction with **bold**, *italic* and \`code\`.

## Plan

* [ ] first task
* [x] second task

| Tool | Purpose |
| - | - |
| Git | versions |

> A quote worth keeping.

\`\`\`python
print("hello")
\`\`\`
`;

/**
 * Markup generated by the third-party editor: wrapped list items and unlabelled table handles.
 * The text stays reachable through the Markdown source view. Review by 2027-06-30.
 */
const EDITOR_INTERNALS = [".rich-text ul", ".rich-text ol", ".rich-text button"];

async function expectAccessible(page: Page, name: string): Promise<void> {
  await page.screenshot({ path: `/reports/screens/${name}.png` });
  const axe = new AxeBuilder({ page });
  for (const selector of EDITOR_INTERNALS) {
    axe.exclude(selector);
  }
  const { violations } = await axe.analyze();
  const summary = violations.map(({ id, nodes }) => `${id}: ${nodes[0]?.html}`);
  expect(summary).toEqual([]);
}

for (const colorScheme of ["light", "dark"] as const) {
  test.describe(colorScheme, () => {
    test.use({ colorScheme });

    test("sign-in has no accessibility violations", async ({ page, context }) => {
      await context.clearCookies();
      await page.goto("/");
      await page.getByLabel("E-mail").waitFor();
      await expectAccessible(page, `sign-in-${colorScheme}`);
    });

    test("main views have no accessibility violations", async ({ notebook, page }) => {
      await page.goto("/");
      await page.getByText("Your library is empty").waitFor();
      await expectAccessible(page, `empty-${colorScheme}`);

      const item = await notebook.seedPage(TEXT, "Cloud and DevOps");
      const folder = await notebook.seed("folder", "Studies");
      await notebook.seed("notebook", "Mathematics", folder);
      await notebook.open(item);
      await notebook.text.getByRole("heading", { name: "Plan" }).waitFor();
      await expectAccessible(page, `page-${colorScheme}`);

      await page.getByRole("button", { name: "Version history" }).click();
      await page.getByRole("button", { name: /Current version/ }).waitFor();
      await expectAccessible(page, `versions-${colorScheme}`);

      await page.getByRole("button", { name: /more within minutes/ }).click();
      await page.getByRole("button", { name: /Version 1/ }).click();
      await page.getByRole("dialog").locator("del").first().waitFor();
      await expectAccessible(page, `version-${colorScheme}`);
      await page.keyboard.press("Escape");

      await notebook.actionsOf("Studies").click();
      await page.getByRole("menuitem", { name: "Move to trash" }).click();
      await page.goto("/trash");
      await page.getByRole("button", { name: "Restore Studies" }).waitFor();
      await expectAccessible(page, `trash-${colorScheme}`);
    });
  });
}

test("the narrow layout shows the page and the library on demand", async ({ notebook, page }) => {
  await page.setViewportSize({ width: 390, height: 780 });
  await notebook.open(await notebook.seedPage(TEXT, "On the phone"));
  await expectAccessible(page, "narrow-page");
  await page.getByRole("button", { name: "Show library" }).click();
  await expect(notebook.library).toBeVisible();
  await page.screenshot({ path: "/reports/screens/narrow-library.png" });
  await page.getByRole("link", { name: "Trash" }).click();
  await page.getByRole("button", { name: "Hide library" }).click();
  await expect(page.getByRole("heading", { name: "Trash", exact: true })).toBeVisible();
});
